<script>
const agreementBase = @json($agreed);
function togglePayment(id){document.getElementById('payment-'+id)?.classList.toggle('hidden')}
function moveStage(button,direction){const row=button.closest('tr.stage-row'),tbody=document.getElementById('schedule-body');const rows=[...tbody.querySelectorAll('tr.stage-row')];const index=rows.indexOf(row),next=rows[index+direction];if(!next)return;const pair=(r)=>{const following=r.nextElementSibling;return following&&following.id==='payment-'+r.dataset.id?following:null};const child=pair(row);if(direction<0){tbody.insertBefore(row,next);if(child)tbody.insertBefore(child,next)}else{const anchor=pair(next)?.nextSibling||next.nextSibling;tbody.insertBefore(row,anchor);if(child)tbody.insertBefore(child,anchor)}[...tbody.querySelectorAll('tr.stage-row')].forEach((r,i)=>r.firstElementChild.textContent=i+1)}
function parseMoney(value){return Number(String(value).replace(/,/g,''))}
document.querySelectorAll('tr.stage-row').forEach(row=>{const percent=row.querySelector('.stage-percent'),amount=row.querySelector('.stage-amount');if(!amount)return;percent?.addEventListener('input',()=>{const n=parseMoney(percent.value);if(Number.isFinite(n)&&agreementBase>0)amount.value=(Math.round(agreementBase*n)/100).toFixed(2)});amount.addEventListener('input',()=>{const n=parseMoney(amount.value);if(percent&&Number.isFinite(n)&&agreementBase>0)percent.value=(n/agreementBase*100).toFixed(4)})});
function saveSchedule(){const form=document.getElementById('schedule-form'),container=document.getElementById('schedule-hidden');if(!form)return;container.replaceChildren();const rows=[...document.querySelectorAll('tr.stage-row')];for(let i=0;i<rows.length;i++){const row=rows[i],amount=parseMoney(row.querySelector('.stage-amount')?.value),title=row.querySelector('.stage-title')?.value.trim();if(!title||!Number.isFinite(amount)||amount<0){alert('Enter a valid stage name and amount in row '+(i+1));return}const data={id:row.dataset.id,title,scheduled_amount:amount.toFixed(2),updated_at:row.dataset.updated};for(const [k,v] of Object.entries(data)){const input=document.createElement('input');input.type='hidden';input.name=`rows[${i}][${k}]`;input.value=v;container.appendChild(input)}}form.submit()}
</script>
